{
  "permissions": {
    "allow": [
      "Bash(git -C /Users/matheusjericopalhares/Documents/ai-bootcamp/spec-agend-sdd log --oneline -10)",
      "WebSearch",
      "WebFetch(domain:smithery.ai)",
      "Bash(claude mcp:*)",
      "Bash(npx:*)",
      "Bash(echo \"not in /opt/homebrew/bin\" echo \"---\" echo \"PATH: $PATH\")",
      "Bash(export PATH=\"/opt/homebrew/bin:/usr/local/bin:$PATH\":*)",
      "Bash(node --version:*)",
      "Bash(git -C /Users/matheusjericopalhares/Documents/arvo/dna-dataform log --oneline -15)",
      "Bash(xargs basename:*)",
      "Bash(git -C /Users/matheusjericopalhares/Documents/arvo/dna-dataform log --oneline --since=\"2024-12-01\")",
      "Bash(find:*)",
      "mcp__ref-tools__ref_read_url",
      "WebFetch(domain:www.googlecloudcommunity.com)",
      "WebFetch(domain:discuss.google.dev)",
      "mcp__exa__web_search_exa",
      "mcp__exa__get_code_context_exa",
      "WebFetch(domain:datatovalue.blog)",
      "WebFetch(domain:medium.com)",
      "WebFetch(domain:www.measurelab.co.uk)",
      "WebFetch(domain:skotlandbi.com)",
      "mcp__ref-tools__ref_search_documentation",
      "WebFetch(domain:docs.cloud.google.com)",
      "Bash(bq show:*)",
      "Bash(python3:*)"
    ],
    "defaultMode": "auto"
  },
  "model": "opus[1m]",
  "enableAllProjectMcpServers": true,
  "enabledMcpjsonServers": [
    "upstash-context7",
    "exa",
    "ref-tools"
  ],
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "~/.claude/hooks/require-claude-coauthor.sh",
            "timeout": 5
          }
        ]
      },
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "rtk hook claude"
          }
        ]
      }
    ]
  },
  "enabledPlugins": {
    "frontend-design@claude-plugins-official": true,
    "context7@claude-plugins-official": true,
    "superpowers@claude-plugins-official": false,
    "skill-creator@claude-plugins-official": true,
    "document-skills@anthropic-agent-skills": true,
    "ui-ux-pro-max@ui-ux-pro-max-skill": true,
    "learning-output-style@claude-plugins-official": true,
    "caveman@caveman": false,
    "codex@openai-codex": true,
    "dark-factory@dark-factory-local": true
  },
  "extraKnownMarketplaces": {
    "ui-ux-pro-max-skill": {
      "source": {
        "source": "github",
        "repo": "nextlevelbuilder/ui-ux-pro-max-skill"
      }
    },
    "caveman": {
      "source": {
        "source": "github",
        "repo": "JuliusBrussee/caveman"
      }
    },
    "openai-codex": {
      "source": {
        "source": "github",
        "repo": "openai/codex-plugin-cc"
      }
    },
    "dark-factory-local": {
      "source": {
        "source": "directory",
        "path": "/Users/matheusjericopalhares/Documents/personal/dark-factory"
      }
    }
  },
  "effortLevel": "xhigh",
  "tui": "fullscreen",
  "skipDangerousModePermissionPrompt": true,
  "agentPushNotifEnabled": true,
  "skipAutoPermissionPrompt": true,
  "voiceEnabled": true
}

